const svg=$('#scm-svg'), out=$('#scm-out');
const a=$('#scm-a'), aL=$('#scm-a-lbl'), b=$('#scm-b'), bL=$('#scm-b-lbl'), c=$('#scm-c'), cL=$('#scm-c-lbl');
const W=640,H=300;
// Linear-Gaussian SCM, all exogenous noises standard normal & independent:
//   Z := Uz                       Var(Z)=1
//   X := a Z + Ux                  Var(X)=a^2+1
//   Y := b X + c Z + Uy            Var(Y)=b^2 Var(X)+c^2+2 b c a + 1
// Closed-form covariances (mean zero throughout).
function stats(){
  const A=+a.value, B=+b.value, C=+c.value;
  const vZ=1, vX=A*A+1;
  const covXZ=A;                       // Cov(X,Z)=a
  const vY=B*B*vX + C*C + 2*B*C*A + 1; // expand Var(bX+cZ+Uy)
  const covXY=B*vX + C*covXZ;          // Cov(X,Y)=b Var(X)+c Cov(X,Z)
  const covYZ=B*covXZ + C*vZ;          // Cov(Y,Z)=b Cov(X,Z)+c
  const corrXY=covXY/Math.sqrt(vX*vY);
  return {A,B,C,vZ,vX,vY,covXZ,covXY,covYZ,corrXY};
}
function render(){
  svg.innerHTML='';
  const s=stats();
  aL.textContent='a = '+s.A.toFixed(1); bL.textContent='b = '+s.B.toFixed(1); cL.textContent='c = '+s.C.toFixed(1);
  const Z=[320,70], X=[170,210], Y=[470,210];
  drawArrow(svg, Z, X, {color:'var(--violet)', markerId:'arr-scm', width:2, label:'a', labelSide:0});
  drawArrow(svg, X, Y, {color:'var(--yellow)', markerId:'arr-scm', width:2.4, label:'b'});
  drawArrow(svg, Z, Y, {color:'var(--violet)', markerId:'arr-scm', width:2, label:'c'});
  drawNode(svg, Z[0],Z[1],'Z',{r:26,fill:'var(--panel2)',stroke:'var(--violet)'});
  drawNode(svg, X[0],X[1],'X',{r:26,fill:'var(--panel2)',stroke:'var(--cyan)'});
  drawNode(svg, Y[0],Y[1],'Y',{r:26,fill:'var(--panel2)',stroke:'var(--yellow)'});
  function cap(x,y,t){ const e=SVG('text',{x,y,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); e.textContent=t; svg.appendChild(e); }
  cap(Z[0],Z[1]-34,'confounder'); cap(X[0],X[1]+44,'treatment'); cap(Y[0],Y[1]+44,'outcome');
  out.textContent =
    'structural equations:   Z := Uz,   X := a·Z + Ux,   Y := b·X + c·Z + Uy   (Uz,Ux,Uy iid standard normal)\n'+
    'entailed joint factorizes as  p(z,x,y) = p(z)·p(x | z)·p(y | x,z)\n'+
    'Var(Z) = '+s.vZ.toFixed(2)+',   Var(X) = '+s.vX.toFixed(2)+',   Var(Y) = '+s.vY.toFixed(2)+'\n'+
    'Cov(X,Z) = '+s.covXZ.toFixed(2)+',   Cov(X,Y) = '+s.covXY.toFixed(2)+',   Cov(Y,Z) = '+s.covYZ.toFixed(2)+'\n'+
    'observed corr(X,Y) = '+s.corrXY.toFixed(3)+'   — this mixes the direct effect b with the confounding path through Z (slope b + c·a/Var(X)).';
}
a.addEventListener('input',render);
b.addEventListener('input',render);
c.addEventListener('input',render);
render();

const svg=$('#do-svg'), out=$('#do-out'), conf=$('#do-conf'), confL=$('#do-conf-lbl'), bObs=$('#do-obs'), bInt=$('#do-int');
const W=640,H=320;
// Binary confounded model Z -> X, Z -> Y, X -> Y. All binary.
// P(Z=1)=0.5. P(X=1 | Z) depends on confounding strength s: a high-Z patient is more likely treated.
// P(Y=1 | X,Z): both the treatment X and the confounder Z raise recovery.
let mode='obs'; // 'obs' = condition on X=1, 'int' = do(X=1)
const pZ=0.5;
function pXgivenZ(z){ const s=+conf.value; return z? 0.5+0.45*s : 0.5-0.45*s; } // s=0 -> X⟂Z
function pYgivenXZ(x,z){ let p=0.30; if(x) p+=0.30; if(z) p+=0.25; return p; }   // X is the true cause (+0.30)
// P(Y=1 | X=1)   = Σ_z P(Y=1|1,z) P(z|X=1)        (conditioning: reweight Z by posterior)
// P(Y=1 | do(X=1)) = Σ_z P(Y=1|1,z) P(z)          (intervention: Z keeps its marginal)
function results(){
  // posterior P(z | X=1)
  const num1=pXgivenZ(1)*pZ, num0=pXgivenZ(0)*(1-pZ); const den=num1+num0;
  const postZ1=num1/den, postZ0=num0/den;
  const obs = pYgivenXZ(1,1)*postZ1 + pYgivenXZ(1,0)*postZ0;
  const intv= pYgivenXZ(1,1)*pZ    + pYgivenXZ(1,0)*(1-pZ);
  // also the true causal contrast P(Y=1|do(X=1)) - P(Y=1|do(X=0))
  const intv0= pYgivenXZ(0,1)*pZ + pYgivenXZ(0,0)*(1-pZ);
  return {obs,intv,ate:intv-intv0,postZ1};
}
function render(){
  svg.innerHTML='';
  confL.textContent='confounding = '+(+conf.value).toFixed(2);
  bObs.classList.toggle('active', mode==='obs');
  bInt.classList.toggle('active', mode==='int');
  const r=results();
  const cut = (mode==='int'); // do(X=1) cuts the Z->X arrow
  const Z=[320,60], X=[170,180], Y=[470,180];
  if(!cut) drawArrow(svg, Z, X, {color:'var(--violet)', markerId:'arr-do', width:2});
  else { // draw the severed arrow as a faint dashed stub with a scissors cue
    drawArrow(svg, Z, X, {color:'var(--line)', markerId:'arr-do-cut', width:1.5, dash:'5 5'});
    const sc=SVG('text',{x:245,y:118,'font-size':18,fill:'var(--pink)'}); sc.textContent='✂'; svg.appendChild(sc);
  }
  drawArrow(svg, Z, Y, {color:'var(--violet)', markerId:'arr-do', width:2});
  drawArrow(svg, X, Y, {color:'var(--yellow)', markerId:'arr-do', width:2.4});
  drawNode(svg, Z[0],Z[1],'Z',{r:24,fill:'var(--panel2)',stroke:'var(--violet)'});
  drawNode(svg, X[0],X[1],'X=1',{r:26,fill: cut?'var(--green)':'var(--panel2)',stroke:'var(--cyan)'});
  drawNode(svg, Y[0],Y[1],'Y',{r:24,fill:'var(--panel2)',stroke:'var(--yellow)'});
  function cap(x,y,t,c){ const e=SVG('text',{x,y,'text-anchor':'middle','font-size':12,fill:c||'var(--mute)'}); e.textContent=t; svg.appendChild(e); }
  cap(Z[0],Z[1]-32,'confounder Z'); cap(X[0],X[1]+44, cut?'set by intervention':'treatment'); cap(Y[0],Y[1]+40,'recovery Y');
  // two bars comparing P(Y=1) under the current mode and the other one
  function bar(x,label,val,col){ const bx=x, by=270, bw=120, full=120; svg.appendChild(SVG('rect',{x:bx,y:by-full,width:bw,height:full,rx:4,fill:'var(--panel2)'})); svg.appendChild(SVG('rect',{x:bx,y:by-full*val,width:bw,height:full*val,rx:4,fill:col,opacity:0.9})); const t=SVG('text',{x:bx+bw/2,y:by+18,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); t.textContent=label; svg.appendChild(t); const v=SVG('text',{x:bx+bw/2,y:by-full*val-6,'text-anchor':'middle','font-size':12,fill:col}); v.textContent=val.toFixed(3); svg.appendChild(v); }
  bar(360,'P(Y=1 | X=1)', r.obs, mode==='obs'?'var(--cyan)':'var(--mute)');
  bar(500,'P(Y=1 | do X=1)', r.intv, mode==='int'?'var(--green)':'var(--mute)');
  const head = mode==='obs'
    ? 'CONDITIONING on X=1: keep only treated units, reweight Z by the posterior P(Z | X=1)'
    : 'INTERVENING do(X=1): cut Z→X, so Z keeps its marginal P(Z); the truncated factorization';
  out.textContent =
    head+'\n'+
    'P(Y=1 | X=1)      = Σ_z P(Y=1 | 1,z)·P(z | X=1)   = '+r.obs.toFixed(3)+'   (posterior P(Z=1 | X=1) = '+r.postZ1.toFixed(3)+')\n'+
    'P(Y=1 | do(X=1))  = Σ_z P(Y=1 | 1,z)·P(z)         = '+r.intv.toFixed(3)+'\n'+
    'gap (confounding bias) = '+(r.obs-r.intv).toFixed(3)+'   — vanishes only when Z does not drive X (confounding = 0)\n'+
    'true causal effect  P(Y=1|do(X=1)) − P(Y=1|do(X=0)) = '+r.ate.toFixed(3)+'   (the genuine lift from treating)';
}
conf.addEventListener('input',render);
bObs.addEventListener('click',()=>{ mode='obs'; render(); });
bInt.addEventListener('click',()=>{ mode='int'; render(); });
render();

const svg=$('#simpson-svg'), out=$('#simpson-out'), alloc=$('#simp-alloc'), allocL=$('#simp-alloc-lbl'), bAdj=$('#simp-adjust'), bReset=$('#simp-reset');
const W=640,H=320;
// Fixed within-stratum recovery rates (the drug helps in BOTH strata).
const rLowT=0.93, rLowU=0.87, rHighT=0.73, rHighU=0.69;
const pHigh=0.5; // population is half high-risk, half low-risk (the marginal P(Z) used for adjustment)
let showAdj=false;
function compute(){
  const fHighT=+alloc.value;     // of the treated, this fraction are high-risk
  const fHighU=1-fHighT;         // mirror: untreated skew the opposite way (the confounding)
  // pooled (naive) rates, weighting each arm by its OWN stratum mix
  const pooledT = fHighT*rHighT + (1-fHighT)*rLowT;
  const pooledU = fHighU*rHighU + (1-fHighU)*rLowU;
  const naive = pooledT - pooledU;
  // adjusted: average within-stratum effects against the POPULATION mix pHigh
  const adjT = pHigh*rHighT + (1-pHigh)*rLowT;
  const adjU = pHigh*rHighU + (1-pHigh)*rLowU;
  const adjusted = adjT - adjU;
  const wLow=rLowT-rLowU, wHigh=rHighT-rHighU;
  return {naive,adjusted,wLow,wHigh,pooledT,pooledU};
}
function render(){
  svg.innerHTML='';
  allocL.textContent='skew = '+(+alloc.value).toFixed(2);
  bAdj.classList.toggle('active', showAdj);
  const r=compute();
  // zero baseline, bars centered
  const baseY=180, scale=520; // px per unit effect
  svg.appendChild(SVG('line',{x1:60,y1:baseY,x2:W-30,y2:baseY,stroke:'var(--mute)','stroke-dasharray':'4 4'}));
  const z0=SVG('text',{x:50,y:baseY+4,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); z0.textContent='0'; svg.appendChild(z0);
  function bar(x,label,val,col){ const bw=90; const h=val*scale; const top=val>=0?baseY-h:baseY; svg.appendChild(SVG('rect',{x,y:top,width:bw,height:Math.abs(h),rx:4,fill:col,opacity:0.9})); const t=SVG('text',{x:x+bw/2,y:baseY+(val>=0?24:-8),'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); t.textContent=label; svg.appendChild(t); const v=SVG('text',{x:x+bw/2,y:(val>=0?baseY-h-6:baseY+h+16),'text-anchor':'middle','font-size':12,fill:col}); v.textContent=(val>=0?'+':'')+val.toFixed(3); svg.appendChild(v); }
  bar(90,'low-risk effect', r.wLow, 'var(--green)');
  bar(200,'high-risk effect', r.wHigh, 'var(--green)');
  bar(340,'pooled (naive)', r.naive, r.naive<0?'var(--pink)':'var(--cyan)');
  if(showAdj) bar(470,'adjusted', r.adjusted, 'var(--yellow)');
  const cap=SVG('text',{x:W/2,y:30,'text-anchor':'middle','font-size':13,fill:'var(--mute)'}); cap.textContent='treatment effect on recovery (higher = drug helps)'; svg.appendChild(cap);
  out.textContent =
    'within-stratum effects (fixed):  low-risk = +'+r.wLow.toFixed(3)+',   high-risk = +'+r.wHigh.toFixed(3)+'   — the drug helps in BOTH strata\n'+
    'pooled (naive)  P(Y=1|X=1) − P(Y=1|X=0) = '+r.pooledT.toFixed(3)+' − '+r.pooledU.toFixed(3)+' = '+(r.naive>=0?'+':'')+r.naive.toFixed(3)+(r.naive<0?'   ← REVERSED! Simpson\'s paradox':'')+'\n'+
    (showAdj
      ? 'adjusted (backdoor)  Σ_z [P(Y=1|X=1,z) − P(Y=1|X=0,z)]·P(z) = +'+r.adjusted.toFixed(3)+'   — averages the true within-stratum effects against the population risk mix; sign restored'
      : 'press "show adjusted effect" to apply Σ_z P(Y|x,z)·P(z) and recover the truth');
}
alloc.addEventListener('input',render);
bAdj.addEventListener('click',()=>{ showAdj=true; render(); });
bReset.addEventListener('click',()=>{ showAdj=false; render(); });
render();

const svg=$('#fd-svg'), out=$('#fd-out'), u=$('#fd-u'), uL=$('#fd-u-lbl');
const W=640,H=320;
// Front-door model X -> M -> Y, with unobserved U -> X and U -> Y.  All binary, U binary 50/50.
// Mechanisms (the causal truth, fixed):
//   P(M=1 | X) = 0.15 + 0.70*X     (smoking strongly produces tar; NOT affected by U)
//   P(Y=1 | M,U) = 0.10 + 0.55*M + g*U   (tar causes cancer; U also raises cancer)
//   P(X=1 | U) = 0.5 - k + 2k*U    where k = confounding slider (U raises urge to smoke)
function pMgivenX(x){ return 0.15 + 0.70*x; }
function pYgivenMU(m,uu,g){ return 0.10 + 0.55*m + g*uu; }
function pXgivenU(uu,k){ return 0.5 - k + 2*k*uu; }
function compute(){
  const k=+u.value; const g=k; // tie U's outcome effect to its strength for a clean single knob
  // ---- build the full observational table over (U,X,M,Y), U uniform ----
  // we need observational P(x'), P(m|x), P(y|m,x') for the front-door formula, which use NO U.
  // marginal P(X=x') = Σ_u P(x'|u)·0.5
  function pX(xp){ return 0.5*(pXgivenU(xp,k) + 0  ) + 0.5*0; }
  // do it explicitly: P(X=1)=0.5*P(X1|U1)+0.5*P(X1|U0)
  const pX1 = 0.5*pXgivenU(1,k) + 0.5*pXgivenU(0,k); const pX0=1-pX1;
  // P(M=1 | X=x') = pMgivenX(x') (M independent of U given X)
  // P(Y=1 | M=m, X=x') = Σ_u P(Y1|m,u)·P(u | M=m,X=x'); since M⟂U|X and U⟂M, P(u|M,X)=P(u|X)
  function pUgivenX(uu,xp){ const num=(uu? pXgivenU(1,k):pXgivenU(0,k))*0.5; const den=(xp? pX1:pX0); // careful: this is P(u|X=1)
    // recompute properly for X=xp
    const pXgU1 = pXgivenU(1,k), pXgU0=pXgivenU(0,k);
    const joint1 = (xp? pXgU1 : 1-pXgU1)*0.5; // U=1
    const joint0 = (xp? pXgU0 : 1-pXgU0)*0.5; // U=0
    const Z=joint1+joint0; return uu? joint1/Z : joint0/Z;
  }
  function pY1givenMX(m,xp){ return pYgivenMU(m,1,g)*pUgivenX(1,xp) + pYgivenMU(m,0,g)*pUgivenX(0,xp); }
  // ---- front-door estimate of P(Y=1 | do(X=1)) and do(X=0) ----
  function frontdoor(xset){ let s=0; for(let m=0;m<2;m++){ const pm=(m? pMgivenX(xset):1-pMgivenX(xset)); let inner=0; for(let xp=0;xp<2;xp++){ inner += pY1givenMX(m,xp)*(xp? pX1:pX0); } s += pm*inner; } return s; }
  const fdEffect = frontdoor(1) - frontdoor(0);
  // ---- the TRUE causal effect from the mechanisms: P(Y=1|do X) = Σ_m P(m|x) Σ_u P(Y1|m,u)·0.5 ----
  function truth(xset){ let s=0; for(let m=0;m<2;m++){ const pm=(m? pMgivenX(xset):1-pMgivenX(xset)); let yy=0; for(let uu=0;uu<2;uu++) yy += pYgivenMU(m,uu,g)*0.5; s += pm*yy; } return s; }
  const trueEffect = truth(1)-truth(0);
  // ---- naive observational association P(Y=1|X=1)-P(Y=1|X=0) ----
  function pY1givenX(xset){ let s=0; for(let uu=0;uu<2;uu++){ const pu_x = pUgivenX(uu,xset); let ym=0; for(let m=0;m<2;m++){ const pm=(m? pMgivenX(xset):1-pMgivenX(xset)); ym += pm*pYgivenMU(m,uu,g); } s += pu_x*ym; } return s; }
  const naive = pY1givenX(1)-pY1givenX(0);
  return {fdEffect,trueEffect,naive,k};
}
function render(){
  svg.innerHTML='';
  uL.textContent='U = '+(+u.value).toFixed(2);
  const r=compute();
  const Xn=[120,150], Mn=[320,150], Yn=[520,150], Un=[320,50];
  drawArrow(svg, Xn, Mn, {color:'var(--yellow)', markerId:'arr-fd', width:2.4});
  drawArrow(svg, Mn, Yn, {color:'var(--yellow)', markerId:'arr-fd', width:2.4});
  drawArrow(svg, Un, Xn, {color:'var(--pink)', markerId:'arr-fd-u', width:2, dash:'5 4'});
  drawArrow(svg, Un, Yn, {color:'var(--pink)', markerId:'arr-fd-u', width:2, dash:'5 4'});
  drawNode(svg, Xn[0],Xn[1],'X',{r:24,fill:'var(--panel2)',stroke:'var(--cyan)'});
  drawNode(svg, Mn[0],Mn[1],'M',{r:24,fill:'var(--panel2)',stroke:'var(--green)'});
  drawNode(svg, Yn[0],Yn[1],'Y',{r:24,fill:'var(--panel2)',stroke:'var(--yellow)'});
  drawNode(svg, Un[0],Un[1],'U',{r:22,fill:'var(--panel)',stroke:'var(--pink)'});
  function cap(x,y,t,c){ const e=SVG('text',{x,y,'text-anchor':'middle','font-size':12,fill:c||'var(--mute)'}); e.textContent=t; svg.appendChild(e); }
  cap(Xn[0],Xn[1]+42,'smoking'); cap(Mn[0],Mn[1]+42,'tar'); cap(Yn[0],Yn[1]+42,'cancer'); cap(Un[0]+90,Un[1],'U: unobserved (genes)','var(--pink)');
  // bars
  function bar(x,label,val,col){ const bw=120, baseY=290, full=110; svg.appendChild(SVG('rect',{x,y:baseY-full,width:bw,height:full,rx:4,fill:'var(--panel2)'})); svg.appendChild(SVG('rect',{x,y:baseY-full*Math.max(0,val)/0.45,width:bw,height:full*Math.max(0,val)/0.45,rx:4,fill:col,opacity:0.9})); const t=SVG('text',{x:x+bw/2,y:baseY+16,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); t.textContent=label; svg.appendChild(t); const v=SVG('text',{x:x+bw/2,y:baseY-full*Math.max(0,val)/0.45-6,'text-anchor':'middle','font-size':12,fill:col}); v.textContent=val.toFixed(3); svg.appendChild(v); }
  bar(120,'naive assoc.', r.naive, r.naive>r.trueEffect+0.005?'var(--pink)':'var(--cyan)');
  bar(270,'front-door', r.fdEffect, 'var(--green)');
  bar(420,'true effect', r.trueEffect, 'var(--yellow)');
  out.textContent =
    'front-door:  P(Y=1 | do(X=1)) − P(Y=1 | do(X=0)),  identified WITHOUT measuring U:\n'+
    '   Σ_m P(m | x) · Σ_{x\u2032} P(y | m, x\u2032) · P(x\u2032)\n'+
    'naive association  P(Y=1|X=1) − P(Y=1|X=0) = '+r.naive.toFixed(3)+'   ← inflated by the unobserved U\n'+
    'front-door estimate                          = '+r.fdEffect.toFixed(3)+'\n'+
    'true causal effect (from the mechanisms)     = '+r.trueEffect.toFixed(3)+'\n'+
    (Math.abs(r.fdEffect-r.trueEffect)<1e-3
      ? 'front-door matches the truth exactly — and stays put as U grows, while the naive association drifts up with the confounding.'
      : 'front-door tracks the truth; the gap to the naive association is the confounding bias U injects.');
}
u.addEventListener('input',render);
render();

const svg=$('#cf-svg'), out=$('#cf-out');
const xf=$('#cf-xfact'), xfL=$('#cf-xfact-lbl'), yf=$('#cf-yfact'), yfL=$('#cf-yfact-lbl'), xc=$('#cf-xcf'), xcL=$('#cf-xcf-lbl');
const W=640,H=300, b=2; // structural equation Y := b·X + U_Y, b fixed = 2
function render(){
  svg.innerHTML='';
  const X=+xf.value, Yobs=+yf.value, Xp=+xc.value;
  xfL.textContent='X = '+X.toFixed(1); yfL.textContent='Y = '+Yobs.toFixed(1); xcL.textContent='X\u2032 = '+Xp.toFixed(1);
  // ABDUCTION: from Y = b·X + U  ⇒  U = Y − b·X (deterministic SCM pins U exactly)
  const U = Yobs - b*X;
  // ACTION + PREDICTION: Y' = b·X' + U  (same U!)
  const Ycf = b*Xp + U;
  const ite = Ycf - Yobs; // individual-level effect of changing X to X'
  // diagram: factual world vs counterfactual world
  function world(cx, title, xv, yv, uv, col){
    const t=SVG('text',{x:cx,y:36,'text-anchor':'middle','font-size':13,fill:col,'font-weight':600}); t.textContent=title; svg.appendChild(t);
    const Xn=[cx-70,110], Yn=[cx+70,110], Un=[cx+70,40];
    drawArrow(svg, Xn, Yn, {color:col, markerId:'arr-cf-'+col.replace(/[^a-z]/g,''), width:2.2, label:'·b'});
    drawArrow(svg, Un, Yn, {color:'var(--mute)', markerId:'arr-cf-u', width:1.5, dash:'4 3'});
    drawNode(svg, Xn[0],Xn[1], xv.toFixed(1), {r:22,fill:'var(--panel2)',stroke:'var(--cyan)'});
    drawNode(svg, Yn[0],Yn[1], yv.toFixed(1), {r:22,fill:'var(--panel2)',stroke:col});
    drawNode(svg, Un[0],Un[1], 'U='+uv.toFixed(1), {r:20,fill:'var(--panel)',stroke:'var(--mute)',fontSize:11});
    const lx=SVG('text',{x:Xn[0],y:Xn[1]+38,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); lx.textContent='X'; svg.appendChild(lx);
    const ly=SVG('text',{x:Yn[0],y:Yn[1]+38,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); ly.textContent='Y'; svg.appendChild(ly);
  }
  world(170,'factual world', X, Yobs, U, 'var(--yellow)');
  world(470,'counterfactual world', Xp, Ycf, U, 'var(--green)');
  const mid=SVG('text',{x:W/2,y:200,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); mid.textContent='same abducted noise U bridges the two worlds'; svg.appendChild(mid);
  out.textContent =
    'structural equation:   Y := b·X + U,   b = '+b+'\n'+
    '1) ABDUCTION:   observe X='+X.toFixed(1)+', Y='+Yobs.toFixed(1)+'  ⇒  U = Y − b·X = '+Yobs.toFixed(1)+' − '+b+'·'+X.toFixed(1)+' = '+U.toFixed(1)+'\n'+
    '2) ACTION:      do(X = '+Xp.toFixed(1)+'),  holding the SAME U = '+U.toFixed(1)+'\n'+
    '3) PREDICTION:  Y_{X\u2032} = b·X\u2032 + U = '+b+'·'+Xp.toFixed(1)+' + '+U.toFixed(1)+' = '+Ycf.toFixed(1)+'\n'+
    'counterfactual: had X been '+Xp.toFixed(1)+' instead of '+X.toFixed(1)+', this unit would have had Y = '+Ycf.toFixed(1)+'\n'+
    'individual treatment effect  Y_{X\u2032} − Y = '+ite.toFixed(1)+'   (consistency: at X\u2032 = X the two worlds coincide, Y_{X} = Y).';
}
xf.addEventListener('input',render);
