const svg=$('#ate-svg'), out=$('#ate-out'), conf=$('#ate-conf'), confL=$('#ate-conf-lbl'), nsl=$('#ate-n'), nL=$('#ate-n-lbl'), bDraw=$('#ate-draw');
const W=640,H=300;
// Confounded binary model. Z ~ Bernoulli(0.5). e(z)=P(X=1|z)=0.5 + s·(2z-1) (high-Z treated more).
// P(Y=1 | X,Z) = 0.30 + TAU*X + 0.30*Z, with the TRUE per-unit effect TAU = 0.20 (constant).
const TAU=0.20;
let seed=24681; function rnd(){ seed=(seed*1664525+1013904223)>>>0; return seed/4294967296; }
function eZ(z){ const s=+conf.value; return 0.5 + s*(2*z-1); }
function pY1(x,z){ return 0.30 + TAU*x + 0.30*z; }
function draw(){
  const n=Math.round(+nsl.value); const s=+conf.value;
  // accumulators for the three estimators
  let sumYt=0,nt=0, sumYc=0,nc=0;                 // naive diff-in-means
  const strat={0:{yt:0,nt:0,yc:0,nc:0,n:0}, 1:{yt:0,nt:0,yc:0,nc:0,n:0}}; // adjustment
  let ipw1=0, ipw0=0;                              // IPW sums (Σ X Y/e + Σ (1-X)Y/(1-e))
  for(let i=0;i<n;i++){
    const z = rnd()<0.5?1:0;
    const x = rnd()<eZ(z)?1:0;
    const y = rnd()<pY1(x,z)?1:0;
    if(x){ sumYt+=y; nt++; } else { sumYc+=y; nc++; }
    const st=strat[z]; st.n++; if(x){ st.yt+=y; st.nt++; } else { st.yc+=y; st.nc++; }
    const e=eZ(z);
    if(x) ipw1 += y/e; else ipw0 += y/(1-e);
  }
  const naive = (nt? sumYt/nt:0) - (nc? sumYc/nc:0);
  // adjustment: Σ_z [ Ȳ(1,z) − Ȳ(0,z) ] · p̂(z)
  let adj=0; for(const z of [0,1]){ const st=strat[z]; const e1=st.nt? st.yt/st.nt:0, e0=st.nc? st.yc/st.nc:0; adj += (e1-e0)*(st.n/n); }
  const ipw = ipw1/n - ipw0/n;
  return {n,naive,adj,ipw,truth:TAU};
}
let res=null;
function render(){
  svg.innerHTML='';
  confL.textContent='confounding = '+(+conf.value).toFixed(2);
  nL.textContent='n = '+Math.round(+nsl.value);
  if(!res) res=draw();
  const baseY=210, full=160, scale=full/0.5; // 0..0.5 effect range
  svg.appendChild(SVG('line',{x1:90,y1:baseY,x2:W-30,y2:baseY,stroke:'var(--mute)'}));
  // true effect reference line
  const ty=baseY-res.truth*scale; svg.appendChild(SVG('line',{x1:90,y1:ty,x2:W-30,y2:ty,stroke:'var(--yellow)','stroke-dasharray':'5 4'}));
  const tl=SVG('text',{x:W-32,y:ty-6,'text-anchor':'end','font-size':11,fill:'var(--yellow)'}); tl.textContent='true ATE = '+res.truth.toFixed(2); svg.appendChild(tl);
  function bar(x,label,val,col){ const bw=110; const h=val*scale; svg.appendChild(SVG('rect',{x,y:baseY-h,width:bw,height:Math.abs(h),rx:4,fill:col,opacity:0.9})); const t=SVG('text',{x:x+bw/2,y:baseY+18,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); t.textContent=label; svg.appendChild(t); const v=SVG('text',{x:x+bw/2,y:baseY-h-6,'text-anchor':'middle','font-size':12,fill:col}); v.textContent=val.toFixed(3); svg.appendChild(v); }
  bar(120,'naive', res.naive, 'var(--pink)');
  bar(280,'adjustment', res.adj, 'var(--cyan)');
  bar(440,'IPW', res.ipw, 'var(--green)');
  const cap=SVG('text',{x:W/2,y:40,'text-anchor':'middle','font-size':13,fill:'var(--mute)'}); cap.textContent='estimated average treatment effect'; svg.appendChild(cap);
  out.textContent =
    'true ATE  τ = E[Y₁] − E[Y₀] = '+res.truth.toFixed(3)+'   (constant per-unit effect built into the model)\n'+
    'naive diff-in-means       = '+res.naive.toFixed(3)+'   bias = '+(res.naive-res.truth>=0?'+':'')+(res.naive-res.truth).toFixed(3)+'   ← confounding inflates it\n'+
    'covariate adjustment      = '+res.adj.toFixed(3)+'   Σ_z [Ȳ(1,z) − Ȳ(0,z)]·p̂(z)\n'+
    'inverse-propensity (IPW)  = '+res.ipw.toFixed(3)+'   (1/n) Σ [ X·Y/e(Z) − (1−X)·Y/(1−e(Z)) ]\n'+
    'sample size n = '+res.n+'.  Adjustment and IPW both target the true τ; the naive estimate carries the confounding bias. Draw again to see sampling noise.';
}
